{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "seek a higher cap supported by the deal’s risk profile and diligence."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek lower thresholds and a tipping basket (recovery from the first dollar once crossed), with appropriate aggregation rules."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer period; tax claims should run through the relevant statutory period plus a buffer."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Capacity and title must not share the general cap or time limits."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Strengthen caps, baskets and survival periods, with materially better treatment for title/fundamental warranties and express carve-outs for fraud and specific indemnities."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "At minimum, reject blanket disclosure of all data-room contents and public registers as automatic qualification of every warranty."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject constructive/imputed knowledge and adviser-knowledge bars"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require final, unconditional written consent and evidence of satisfaction of all conditions as a condition precedent to Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark debt and security must be discharged at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require these amounts and associated on-costs to be expressly allocated to Seller, deducted from proceeds or treated as debt-like items"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require, before Completion, evidence of cleared payment and a binding assignment/confirmation of all relevant IP rights"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require a completed investigation, preservation of evidence, confirmation of containment and any required notifications/remediation, plus a specific indemnity"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Review the contracts and timing; ensure accrued/unpaid amounts are reflected as working capital or debt-like items as appropriate, and obtain consent if needed."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Preserve carve-outs for fraud, wilful concealment, title/fundamental claims, specific indemnities, purchase-price adjustments and other negotiated remedies."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "That is useful evidence, not a substitute for robust title warranties and verification of encumbrances, options, beneficial ownership and the complete share capital."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek appropriate tax warranties and a separate tax indemnity, and ensure IP warranties cover ownership, infringement, employee/contractor assignments and licences."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

